<?php
namespace App\Http\Controllers;
use App\Models\DeliveryAddress;
use App\Models\FoodOrder;
use App\Models\FoodOrderEvent;
use App\Models\MenuCategory;
use App\Models\MenuItem;
use App\Models\Promotion;
use App\Models\Restaurant;
use App\Models\User;
use App\Services\OrderCreator;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\Rule;
class FoodController extends Controller {
 public function index(){return view('food.index',['restaurants'=>Restaurant::where('is_open',true)->withCount('items')->orderBy('name')->get()]);}
 public function restaurant(Restaurant $restaurant){$restaurant->load(['categories.items'=>fn($q)=>$q->where('available',true)->where(fn($x)=>$x->whereNull('stock')->orWhere('stock','>',0))]);$uncategorized=$restaurant->items()->whereNull('menu_category_id')->where('available',true)->where(fn($q)=>$q->whereNull('stock')->orWhere('stock','>',0))->get();return view('food.restaurant',compact('restaurant','uncategorized'));}
 public function add(Request $r,Restaurant $restaurant,MenuItem $item){abort_unless($item->restaurant_id===$restaurant->id,404);abort_unless($restaurant->is_open&&$item->available&&($item->stock===null||$item->stock>0),404);$data=$r->validate(['quantity'=>'required|integer|min:1|max:20']);$cart=$r->session()->get('cart',[]);if(isset($cart['restaurant_id'])&&$cart['restaurant_id']!==$restaurant->id)$cart=['restaurant_id'=>$restaurant->id,'items'=>[]];$cart['restaurant_id']=$restaurant->id;$lines=$cart['items']??[];abort_if(!isset($lines[$item->id])&&count($lines)>=30,422,'Cart limit is 30 distinct items.');$cart['items'][$item->id]=min(20,($cart['items'][$item->id]??0)+(int)$data['quantity']);$r->session()->put('cart',$cart);return back()->with('status','Added to cart.');}
 public function cart(Request $r){$cart=$r->session()->get('cart',[]);$restaurant=isset($cart['restaurant_id'])?Restaurant::find($cart['restaurant_id']):null;$items=$restaurant?MenuItem::where('restaurant_id',$restaurant->id)->whereIn('id',array_keys($cart['items']??[]))->get():collect();$addresses=$r->user()->addresses()->latest()->get();return view('food.cart',compact('cart','restaurant','items','addresses'));}
 public function address(Request $r){return view('food.addresses',['addresses'=>$r->user()->addresses()->latest()->get()]);}
 private function addressData(Request $r):array{return $r->validate(['label'=>'nullable|string|max:80','recipient_name'=>'required|string|max:120','phone'=>'required|string|max:30','address_line'=>'required|string|max:255','city'=>'required|string|max:120','postal_code'=>'nullable|string|max:20','delivery_notes'=>'nullable|string|max:1000']);}
 public function saveAddress(Request $r){$r->user()->addresses()->create($this->addressData($r));return back()->with('status','Address saved.');}
 public function updateAddress(Request $r,int $id){$r->user()->addresses()->findOrFail($id)->update($this->addressData($r));return back()->with('status','Address updated.');}
 public function deleteAddress(Request $r,int $id){$r->user()->addresses()->findOrFail($id)->delete();return back()->with('status','Address deleted.');}
 public function checkout(Request $r,OrderCreator $creator){$data=$r->validate(['address_id'=>'required|integer','promotion_code'=>'nullable|string|max:40','customer_note'=>'nullable|string|max:1000']);$cart=$r->session()->get('cart',[]);abort_unless(!empty($cart['restaurant_id'])&&!empty($cart['items']),422,'Cart is empty.');$address=$r->user()->addresses()->findOrFail($data['address_id']);$restaurant=Restaurant::findOrFail($cart['restaurant_id']);$order=$creator->create($r->user(),$restaurant,$address,$cart['items'],$data['promotion_code']??null,$data['customer_note']??null);$r->session()->forget('cart');return redirect()->route('food.orders.show',$order)->with('status','Order placed; payment remains unpaid until cash on delivery.');}
 public function orders(Request $r){$orders=$r->user()->foodOrders()->with('restaurant')->latest()->paginate(20);return view('food.orders',compact('orders'));}
 public function order(Request $r,int $id){$order=FoodOrder::with(['restaurant','items','events'])->findOrFail($id);abort_unless($order->customer_id===$r->user()->id||$r->user()->isAdmin()||($r->user()->isRestaurantOwner()&&$order->restaurant->owner_id===$r->user()->id)||($r->user()->isDeliveryStaff()&&$order->delivery_staff_id===$r->user()->id),404);return view('food.order',compact('order'));}
 public function restaurantDashboard(Request $r){$user=$r->user();abort_unless($user->isRestaurantOwner()||$user->role==='delivery',403);$restaurants=$user->role==='delivery'?collect():($user->isAdmin()?Restaurant::with('categories','items'):$user->restaurants()->with('categories','items'))->get();$orders=FoodOrder::with(['restaurant','customer'])->when($user->role==='delivery',fn($q)=>$q->where('delivery_staff_id',$user->id),fn($q)=>$q->when(!$user->isAdmin(),fn($x)=>$x->whereIn('restaurant_id',$restaurants->pluck('id'))))->latest()->paginate(30);return view('food.restaurant-dashboard',compact('restaurants','orders'));}
 public function createRestaurant(Request $r){abort_unless($r->user()->isAdmin(),403);$owners=User::whereIn('role',['restaurant','admin'])->orderBy('name')->get();return view('food.create-restaurant',compact('owners'));}
 public function storeRestaurant(Request $r){abort_unless($r->user()->isAdmin(),403);$data=$r->validate(['owner_id'=>['required',Rule::exists('users','id')->whereIn('role',['restaurant','admin'])],'name'=>'required|string|max:180','description'=>'nullable|string|max:2000','delivery_fee_cents'=>'required|integer|min:0|max:100000']);$data['slug']=\Illuminate\Support\Str::slug($data['name']).'-'.\Illuminate\Support\Str::lower(\Illuminate\Support\Str::random(5));Restaurant::create($data);return redirect()->route('food.restaurant.dashboard');}
 public function addCategory(Request $r,Restaurant $restaurant){$this->own($r,$restaurant);$data=$r->validate(['name'=>['required','string','max:100',Rule::unique('menu_categories')->where('restaurant_id',$restaurant->id)]]);$restaurant->categories()->create($data);return back()->with('status','Category created.');}
 public function addItem(Request $r,Restaurant $restaurant){$this->own($r,$restaurant);$data=$r->validate(['menu_category_id'=>['nullable','integer',Rule::exists('menu_categories','id')->where('restaurant_id',$restaurant->id)],'name'=>'required|string|max:160','description'=>'nullable|string|max:2000','price_cents'=>'required|integer|min:1|max:10000000','stock'=>'nullable|integer|min:0|max:100000','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:3072']);if($r->hasFile('image'))$data['image_path']=$r->file('image')->store('menu','public');unset($data['image']);$restaurant->items()->create($data);return back()->with('status','Menu item created.');}
 public function updateRestaurant(Request $r,Restaurant $restaurant){$this->own($r,$restaurant);$data=$r->validate(['is_open'=>'required|boolean','delivery_fee_cents'=>'required|integer|min:0|max:100000']);$restaurant->update($data);return back()->with('status','Restaurant settings saved.');}
 public function updateItem(Request $r,Restaurant $restaurant,int $item){$this->own($r,$restaurant);$item=MenuItem::where('restaurant_id',$restaurant->id)->findOrFail($item);$data=$r->validate(['menu_category_id'=>['nullable','integer',Rule::exists('menu_categories','id')->where('restaurant_id',$restaurant->id)],'name'=>'required|string|max:160','description'=>'nullable|string|max:2000','price_cents'=>'required|integer|min:1|max:10000000','stock'=>'nullable|integer|min:0|max:100000','available'=>'required|boolean','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:3072']);if($r->hasFile('image'))$data['image_path']=$r->file('image')->store('menu','public');unset($data['image']);$item->update($data);return back()->with('status','Menu item updated.');}
 public function assignment(Request $r,int $id){$user=$r->user();abort_unless($user->isRestaurantOwner()||$user->isAdmin(),403);$order=FoodOrder::with('restaurant')->findOrFail($id);abort_unless($user->isAdmin()||$order->restaurant->owner_id===$user->id,404);$data=$r->validate(['delivery_staff_id'=>'nullable|integer|exists:users,id']);if($data['delivery_staff_id']&&!User::whereKey($data['delivery_staff_id'])->where('role','delivery')->exists())return back()->withErrors(['delivery_staff_id'=>'Choose an active delivery staff account.']);$order->update(['delivery_staff_id'=>$data['delivery_staff_id']]);return back()->with('status','Delivery assignment saved.');}
 public function transition(Request $r,int $id){$user=$r->user();$data=$r->validate(['status'=>'required|in:accepted,rejected,preparing,ready,picked_up,delivered,cancelled']);return DB::transaction(function()use($r,$user,$data,$id){$order=FoodOrder::with('restaurant')->lockForUpdate()->findOrFail($id);$from=$order->status;$to=$data['status'];$restaurant=$user->isRestaurantOwner()&&$order->restaurant->owner_id===$user->id;$driver=$user->role==='delivery'&&$order->delivery_staff_id===$user->id;$allowed=$restaurant?['pending'=>['accepted','rejected'],'accepted'=>['preparing','cancelled'],'preparing'=>['ready'],'ready'=>[]]:[];if($driver)$allowed=['ready'=>['picked_up'],'picked_up'=>['delivered']];if($user->isAdmin())$allowed=['pending'=>['accepted','rejected','cancelled'],'accepted'=>['preparing','cancelled'],'preparing'=>['ready'],'ready'=>['picked_up'],'picked_up'=>['delivered']];abort_unless(in_array($to,$allowed[$from]??[],true),403,'Unauthorized or invalid order transition.');if(in_array($to,['rejected','cancelled'],true)){foreach($order->items as $line){if($line->menu_item_id)MenuItem::whereKey($line->menu_item_id)->increment('stock',$line->quantity);}}$order->update(['status'=>$to,'payment_status'=>$to==='delivered'?'paid':$order->payment_status]);FoodOrderEvent::create(['food_order_id'=>$order->id,'user_id'=>$user->id,'from_status'=>$from,'to_status'=>$to]);return back()->with('status','Order status updated.');});}
 public function storePromotion(Request $r){abort_unless($r->user()->isAdmin(),403);$r->merge(['code'=>strtoupper(trim((string)$r->input('code')))]);if((bool)$r->filled('discount_percent')===(bool)$r->filled('discount_cents'))throw \Illuminate\Validation\ValidationException::withMessages(['discount_percent'=>'Choose exactly one discount type.']);$data=$r->validate(['code'=>'required|string|max:40|alpha_dash|unique:promotions,code','discount_percent'=>'nullable|integer|min:1|max:100','discount_cents'=>'nullable|integer|min:1|max:10000000','minimum_subtotal_cents'=>'required|integer|min:0|max:10000000','max_uses'=>'nullable|integer|min:1|max:1000000','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at']);$data['active']=true;Promotion::create($data);return back()->with('status','Promotion created.');}
 public function report(Request $r){abort_unless($r->user()->isAdmin(),403);$summary=FoodOrder::select('status',DB::raw('count(*) as orders'),DB::raw('sum(total_cents) as gross_cents'))->groupBy('status')->get();$promotions=Promotion::orderBy('code')->get();return view('food.report',compact('summary','promotions'));}
 private function own(Request $r,Restaurant $restaurant):void{abort_unless($r->user()->isAdmin()||($r->user()->role==='restaurant'&&$restaurant->owner_id===$r->user()->id),404);}
}
